function point(x,y,z=0){return [500+(x-y)*.96,103+(x+y)*.46-z]};const pts=a=>a.map(p=>point(...p).join(',')).join(' ');const poly=(a,fill,stroke='none',sw=1,more='')=>`<polygon points="${pts(a)}" fill="${fill}" stroke="${stroke}" stroke-width="${sw}" ${more}/>`;const line=(a,stroke,sw=1,more='')=>`<polyline points="${pts(a)}" fill="none" stroke="${stroke}" stroke-width="${sw}" ${more}/>`;
