function block(x,y,w,d,h,z=0,c='#34566d',roof='#27475d',edge='#527891'){return poly([[x,y+d,z],[x+w,y+d,z],[x+w,y+d,z+h],[x,y+d,z+h]],c,edge,.65)+poly([[x+w,y,z],[x+w,y+d,z],[x+w,y+d,z+h],[x+w,y,z+h]],'#142d43',edge,.65)+rect(x,y,w,d,z+h,roof,edge,.85)}
