function windows(x,y,w,d,h,z,c,spacing=13){let s='';for(let level=9;level<h-5;level+=13){for(let i=7;i<w-5;i+=spacing){let col=rand()>.25?c:'#29445c';s+=poly([[x+i,y+d+.2,z+level],[x+i+5,y+d+.2,z+level],[x+i+5,y+d+.2,z+level+5],[x+i,y+d+.2,z+level+5]],col,'none',1,`opacity="${rand()>.4?.8:.4}"`)}for(let i=7;i<d-5;i+=spacing){let col=rand()>.35?c:'#2a455b';s+=poly([[x+w+.2,y+i,z+level],[x+w+.2,y+i+5,z+level],[x+w+.2,y+i+5,z+level+5],[x+w+.2,y+i,z+level+5]],col,'none',1,`opacity="${rand()>.4?.7:.35}"`)}}return s}
