if(type==='factory'){for(let i=0;i<2;i++)s+=block(bx+9+i*26,by+8,15,32,13,5+h,'#416274','#52758a',c);let [cx,cy]=point(x+15,y+15,5+h);s+=`<path d="M${cx} ${cy}v-27l18-9 12 8v13" fill="none" stroke="${c}" stroke-width="3" stroke-linejoin="round"/>`;}
if(type==='finance'){let [cx,cy]=point(x,y,5+h);for(let i=0;i<4;i++)s+=block(bx+8+i*11,by+12,8,16,8+i*6,5+h,'#74613f','#b39b60',c);s+=`<circle cx="${cx+22}" cy="${cy-20}" r="12" fill="#3e392b" stroke="${c}"/><text x="${cx+22}" y="${cy-16}" font-size="13" font-weight="700" fill="${c}" text-anchor="middle">€</text>`;}
if(type==='comms'){let [cx,cy]=point(x,y,5+h);s+=`<path d="M${cx} ${cy}v-15M${cx-18} ${cy-34}Q${cx-6} ${cy-2} ${cx+21} ${cy-22}Z" fill="#53436e" stroke="${c}" stroke-width="1.5"/><path d="M${cx} ${cy-21}l13-20" stroke="${c}" stroke-width="2"/><circle cx="${cx+13}" cy="${cy-41}" r="3" fill="${c}" filter="url(#glow)"/>`;}
