SENTINEL:{name:'Centre de surveillance',code:'SEC / 06',stations:[['Bouclier de contrôle','shield','Risques et autorisations','approval'],['Mur de surveillance','wall','Journal de contrôle','agentLog'],['Bureau de SENTINEL','desk','Mission de vérification','agentDetail'],['Contrôle qualité','screens','Livrables et vérifications','campaigns'],['Diagnostics','console','Connecteurs et incidents','connectors']]},
