const select15prev=selectAgent;selectAgent=function(id){select15prev(id);if(!org15[id])return;const a=agents.find(x=>x.id===id),d=org15[id];let h=$('detail').querySelector('h3');if(h)h.textContent=d.title;let sm=$('detail').querySelector('.detail-title small');if(sm)sm.textContent=id==='CORE'?'Infrastructure · DATA CORE':'Directeur : '+id;let w=document.createElement('div');w.className='org-summary15';w.innerHTML=`<h4>Équipe modulable · démo</h4><div class="kv"><span>${id==='CORE'?'Direction dédiée':'Directeur permanent'}</span><b>${id==='CORE'?'Non attribuée':'1'}</b></div><div class="kv"><span>Spécialistes mobilisés</span><b style="color:#55e5b6">${count15(id)} / ${d.roles.length}</b></div><div class="kv"><span>Automate</span><b>${auto15(id)?'Actif':'En veille'}</b></div><button class="secondary" data-team15="${id}">Voir les postes de travail ↗</button>`;$('detail').append(w);};
function stationArt15(a,active,automate=false){let c=a.color;return `<svg viewBox="0 0 140 91" aria-hidden="true"><ellipse cx="70" cy="76" rx="49" ry="11" fill="#000" opacity=".28"/><path d="M18 65L70 39l52 26-52 25z" fill="#172a3c" stroke="#34536a"/><path d="M29 43L81 17l35 17-52 27z" fill="#355168" stroke="#577a91"/><path d="M29 43v13l35 18V61zM64 61v13l52-26V34z" fill="#142c40" stroke="#36546a"/><path d="M72 16l25-12v22L72 39z" fill="${active?'#123f4f':'#16222e'}" stroke="${active?c:'#506075'}"/><path d="M77 19l15-7m-15 12l11-5m-11 10l15-7" stroke="${active?c:'#394b5a'}" stroke-width="1.5"/><path d="M84 34v9" stroke="#7895a7" stroke-width="2"/>${active?(automate?`<g transform="translate(51 70)"><rect x="-12" y="-16" width="24" height="14" rx="4" fill="#647b94" stroke="#b7d2e2"/><rect x="-7" y="-12" width="14" height="5" rx="2" fill="${c}"/><circle cx="-8" r="4" fill="#111e2d"/><circle cx="8" r="4" fill="#111e2d"/><path d="M0 -16v-6" stroke="${c}"/><circle cy="-23" r="2" fill="${c}"/></g>`:`<g transform="translate(51 70)"><path d="M-5-4v7m10-7v7M-9-15l-5 7m23-7 5 7" stroke="#93b0c5" stroke-width="4" stroke-linecap="round"/><rect x="-9" y="-21" width="18" height="17" rx="5" fill="#91a9bb"/><rect x="-14" y="-40" width="28" height="23" rx="8" fill="#d4e5f0"/><rect x="-11" y="-35" width="22" height="12" rx="4" fill="#102334"/><circle cx="-5" cy="-29" r="2.5" fill="${c}"/><circle cx="5" cy="-29" r="2.5" fill="${c}"/><path d="M0-40v-5" stroke="#9ebbd0"/><circle cy="-46" r="2" fill="${c}"/><rect x="-4" y="-16" width="8" height="5" rx="2" fill="${c}"/></g>`):'<path d="M44 67l10-5 10 5-10 5z" fill="#31485d" stroke="#51697c"/><path d="M54 62v-12l10-5v17" fill="#253c50" stroke="#50697f"/>'}</svg>`;}
function planSelect15(){return `<label class="plan-label15">Scénario d’effectifs (simulation)<select data-plan15 aria-label="Scénario d’effectifs">${Object.entries(plans15).map(([id,p])=>`<option value="${id}" ${id===plan15?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label>`}
