const teamPanel15=document.createElement('section');teamPanel15.className='control13 workforce15';teamPanel15.innerHTML=`<div><small>ORGANISATION DYNAMIQUE · DESIGN 22.6</small><strong id="summary15"></strong></div><div class="actions">${planSelect15()}<button class="secondary" id="catalog15">Répertoire des compétences</button></div>`;panel14.after(teamPanel15);
function update15(){ $('summary15').textContent='6 directeurs · '+total15()+' spécialistes mobilisés · '+plans15[plan15].autos.length+' automates actifs (démo)';document.querySelectorAll('[data-plan15]').forEach(e=>e.value=plan15);const n=$('workforceMetric15');if(n){n.innerHTML='6 <span style="font-size:14px;color:#a1cce2">+ '+total15()+'</span>';$('workforceSub15').textContent='Directeurs + spécialistes · démo';} }
