function directory15(){let html=`<div id="directory15"><p>Répertoire initial de 42 compétences réparties entre 7 domaines. Les postes sont des capacités, pas des effectifs permanents. <b>Scénario : ${esc(plans15[plan15].name)}</b></p>${Object.entries(org15).map(([id,d])=>`<div class="directory-row15"><div><strong style="color:${agents.find(a=>a.id===id).color}">${esc(d.title)}</strong><small>${id==='CORE'?'DATA CORE · infrastructure':id+' · directeur'} · ${count15(id)}/6 spécialistes</small><p>${d.roles.map(esc).join(' · ')}</p></div><button class="secondary" data-team15="${id}">Équipe ↗</button></div>`).join('')}</div>`;if($('modal').open){$('modalTitle').textContent='Répertoire des compétences';$('modalBody').innerHTML=html;}else openModal('Répertoire des compétences',html);}
