function screen16(x,y,z,w,h,c,active,n){let s=active?c:'#526477';let q=pol16([[x,y,z],[x+w,y,z],[x+w,y,z+h],[x,y,z+h]],'#091824',s,1.6)+pol16([[x+3,y-.1,z+3],[x+w-3,y-.1,z+3],[x+w-3,y-.1,z+h-3],[x+3,y-.1,z+h-3]],active?'#10323c':'#101a25');for(let j=0;j<4;j++)q+=path16([[x+5,y-.2,z+5+j*5],[x+w-5,y-.2,z+5+j*5]],s,.6,'opacity=".27"');if(active){q+=path16([[x+5,y-.4,z+8],[x+13,y-.4,z+15],[x+20,y-.4,z+11],[x+w-5,y-.4,z+h-6]],c,1.6,'class="screenPulse16"');for(let j=0;j<3;j++)q+=path16([[x+5,y-.3,z+h-5-j*4],[x+10+n%4,y-.3,z+h-5-j*4]],'#c5f7ff',.6)}return q}
