function desk16(a,x,y,i,active,kind='specialist',role=''){let c=a.color,accent=kind==='director'?'#e9bf68':active?c:'#73869a',dir=kind==='director',w=dir?93:78,d=dir?51:43;let [px,py]=P16(x,y+38);let [lx,ly]=P16(x,y+65);let [gx,gy]=P16(x,y+10);let phase=cycle16?.phase;let on=active?'Mobilisé':'Disponible';if(active&&phase===0)on='Arrivée';if(active&&phase===2)on='Libération';if(dir)on='Direction permanente';let out=`<g class="seatScene16" tabindex="0" role="button" data-seat16="${dir?'director':i}" data-dept16="${a.id}" data-active16="${active}" aria-label="${esc(role)} · ${on}"><title>${esc(role)} — ${on}</title>`;out+=floor16(x-w/2-5,y-27,w+10,d+65,1,active?'#14343e':'#172633',active?c:'#354b60');out+=`<ellipse cx="${gx}" cy="${gy}" rx="75" ry="38" fill="${c}" opacity="${active?.08:0}" pointer-events="none"/>`;out+=cube16(x-w/2+3,y-21,8,d-6,22,0,'#38516a')+cube16(x+w/2-11,y-21,8,d-6,22,0,'#38516a')+cube16(x-w/2,y-25,w,d,7,22,dir?'#405a6b':'url(#roof16)');out+=path16([[x-w/2,y+d-25,30],[x+w/2,y+d-25,30]],accent,2);out+=`<g pointer-events="none" aria-hidden="true">${floor16(x-w/2+3,y-23,w-6,d-4,29.15,dir?'url(#deskExecutive21)':'url(#deskSurface21)','#7793a3')}${path16([[x-w/2+4,y-22,30],[x+w/2-4,y-22,30]],'#c3d9e4',.7,'opacity=".55"')}${cube16(x+w/2-15,y-17,10,12,3,30,'#1d3344',accent)}${path16([[x+w/2-13,y-7,34],[x+w/2-7,y-7,34]],accent,1.8)}${path16([[x-w/2+4,y+d-25,26],[x+w/2-4,y+d-25,26]],'#06121e',1.2)}${dir?floor16(x-w/2+8,y-17,11,13,30,'#aa8b50','#edca78'):floor16(x-w/2+6,y-17,10,11,30,'#203b4b',accent)}</g>`;out+=cube16(x-11,y-16,22,11,3,29,'#5f7488')+cube16(x-3,y-15,6,5,12,31,'#5f7488')+screen16(x-31,y-13,41,62,32,accent,active,i);out+=`<g pointer-events="none" aria-hidden="true">${floor16(x-20,y+5,43,12,29.3,'#172937','#476578')}${floor16(x+25,y+6,8,10,29.5,'#0a1723','#61788a')}${path16([[x+29,y+7,30],[x+29,y+11,30]],accent,.65)}${path16([[x-w/2+6,y+d-24,26],[x+w/2-6,y+d-24,26]],'#a1b7c5',.7,'opacity=".5"')}</g>`;
out+=floor16(x-20,y+6,40,9,29.5,'#0b1723','#61788a');for(let j=0;j<6;j++)out+=path16([[x-17+j*6,y+7,30],[x-17+j*6,y+13,30]],accent,.5);out+=cube16(x-10,y+26,20,16,17,0,'#31465a');if(active){let anim=dir?'':phase===0?' arriving16':phase===2?' departing16':'';out+=`<g transform="translate(${px} ${py})"><g class="${anim}" style="--delay16:${i*.11}s">${robot16(c,kind,i)}</g></g>`}else{out+=cube16(x-10,y+41,20,5,18,9,'#31485d');}out+=tag16(lx,ly+8,role,on,accent,dir?153:132);return out+'</g>'}
function autoSeat16(a,x,y){let active=auto15(a.id),c=active?a.color:'#708398',[px,py]=P16(x,y+4),[lx,ly]=P16(x,y+32);return `<g class="seatScene16" tabindex="0" role="button" data-dept16="${a.id}" data-seat16="auto" data-auto-active16="${active}" aria-label="Automate ${active?'actif':'en veille'}"><title>${esc(org15[a.id].auto)}</title>${floor16(x-43,y-28,86,57,1,'#142b3a',c)}${cube16(x-33,y-22,66,43,9,0,'#314b60',c)}<g transform="translate(${px} ${py})"><ellipse rx="27" ry="11" fill="${c}" opacity=".12"/><g class="${active?'bot16':''}"><rect x="-23" y="-32" width="46" height="26" rx="8" fill="url(#metal16)" stroke="#a5bbcf"/><rect x="-17" y="-25" width="34" height="12" rx="4" fill="#0a1929"/><path d="M-10-19H10" stroke="${c}" stroke-width="4" stroke-linecap="round"/><circle cx="-14" cy="-5" r="7" fill="#0b1520" stroke="#6c8599"/><circle cx="14" cy="-5" r="7" fill="#0b1520" stroke="#6c8599"/><path d="M0-32v-8" stroke="#9bb4c8"/><circle cy="-41" r="3" fill="${c}"/></g></g>${tag16(lx,ly+7,'Automate',active?'Actif · script':'En veille',c,114)}</g>`}
