if(dest==='agentLog'){title='Consulter le journal du département';desc='Journal de démonstration du département sélectionné.';}
if(dest==='training12'){title='Ouvrir le simulateur de formation';desc='Choisir un agent, effectuer un exercice local et consulter son résultat.';meta='Simuler · local';}
if(dest==='world'){title='Explorer les marchés par région';desc='Carte de démonstration : six zones géographiques sélectionnables.';}
