if(dest==='opportunities'&&room==='OPPORTUNITIES'){title='Consulter et filtrer les opportunités';desc='Classement, preuves et prochaines étapes issues de la source choisie.';}
if(dest==='products'&&room==='PORTFOLIO'){title='Consulter le portefeuille de produits';desc='Produits et services, état et filtre par activité.';}
if(dest==='investments'&&room==='INVESTMENTS'){title='Examiner les dossiers d’investissement';desc='Hypothèses, montants prévisionnels et état des projets.';}
if(dest==='sync'||dest==='sync13'){meta='Importer · lecture seule';desc='Charger un instantané JSON validé sur le format ; origine non authentifiée.';}
if(dest==='export'&&['GROUP','OPPORTUNITIES','PORTFOLIO','INVESTMENTS','NOTIFICATIONS'].includes(room)){title='Télécharger le portefeuille V2 complet';desc='Exporte toutes les données de la source active, sans appliquer les filtres.';}
if(dest==='export'||dest.toLowerCase().includes('export'))meta='Télécharger · JSON';
