// 16.3.1 : le comportement d'origine de 16.1 est conservé. Aucun intermédiaire de sélection.
(()=>{
 const root=$('roomScene'), selector='svg .seatScene16[data-seat16],svg .station[data-station]';
 let pointer=null,keyboard=null;
 function target(el){return el instanceof Element?el.closest(selector):null;}
 function update(){const svg=root.querySelector(':scope > svg');if(!svg)return;for(const label of svg.querySelectorAll('[data-label-seat1631],[data-label-station1631]')){
 const key=label.dataset.labelSeat1631??label.dataset.labelStation1631;const attr=label.hasAttribute('data-label-seat1631')?'seat16':'station';
 label.classList.toggle('linkedHover1631',[pointer,keyboard].some(n=>n&&svg.contains(n)&&n.dataset[attr]===key));
 }}
 root.addEventListener('pointerover',e=>{const g=target(e.target);if(g!==pointer){pointer=g;update()}});
 root.addEventListener('pointerout',e=>{const g=target(e.relatedTarget);if(g!==pointer){pointer=g;update()}});
 root.addEventListener('pointerleave',()=>{pointer=null;update()});
 root.addEventListener('focusin',e=>{keyboard=target(e.target);update()});
 root.addEventListener('focusout',e=>{keyboard=target(e.relatedTarget);update()});
})();

