function startRun20(id,title){const u=unit20(id),d=div19[id];title=String(title||'').trim();if(mode14!=='demo'){toast('Reviens à la simulation pour mobiliser des ressources.');return false}if(!validUnit20(u)||!d?.slots.length||runs20.has(id)||cycle16||!title||title.length>140){toast('Mission impossible : vérifie la division, ses réservations et son intitulé.');return false}const slots=d.slots.filter(s=>ownerSlot19(s)?.id===id&&!slotRun20(s));if(!slots.length){toast('Aucune capacité disponible.');return false}const r={id:'SIM20-'+String(serial20++).padStart(3,'0'),unit:id,title,slots:[...slots],phase:0,elapsed:0,paused:false,started:now20()};runs20.set(id,r);event20(r,'mobilisation',`${slots.length} spécialiste(s) mobilisé(s)`,{slots:[...slots]});updatePlan20();changePlan15(lifecycleKey20);return true;}
