const lifePanel20=document.createElement('section');lifePanel20.className='control13 lifePanel20';lifePanel20.innerHTML=`<div><small>MISSIONS DES DIVISIONS · DESIGN 22.6</small><strong id="lifeSummary20"> </strong></div><div class="actions"><button class="secondary" data-life20="open">▦ Mobilisation des divisions</button></div>`;teamPanel15.after(lifePanel20);
